import zipfile,xml.etree.ElementTree as ET
p='/home/user/workspace/out_b/Safety_Brief.pptx'; z=zipfile.ZipFile(p)
P='http://schemas.openxmlformats.org/presentationml/2006/main'; A='http://schemas.openxmlformats.org/drawingml/2006/main'
ns={'p':P,'a':A,'r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
for i in range(1,4):
 r=ET.fromstring(z.read(f'ppt/slides/slide{i}.xml'))
 texts=[]
 for sh in r.find('.//p:spTree',ns):
  nm=''
  if sh.tag.endswith('}sp'):
   c=sh.find('./p:nvSpPr/p:cNvPr',ns); nm=c.get('name','') if c is not None else ''
  if nm.startswith(('Title_','Body_','Footer_')): texts.append((nm,''.join(t.text or '' for t in sh.findall('.//a:t',ns))))
 pics=r.findall('.//p:pic',ns)
 print(i,texts,'pictures',len(pics))
PY

